// Bouncer: drops anything that isn't a well-formed Luma feedback payload, rate-limits, and builds the Discord embed.
// Luma sends: { "type": "bug|feature_request|suggestion|other", "title": "...", "description": "...", "version": "2.0.0", "os": "..." }
// Returning [] ends the execution quietly: nothing reaches Discord.
const MAX_TITLE = 120;
const MAX_DESCRIPTION = 2000;
const MAX_BODY = 2600;          // whole JSON body
const PER_IP_LIMIT = 5;         // submissions per IP ...
const PER_IP_WINDOW_MS = 10 * 60 * 1000;   // ... per 10 minutes
const GLOBAL_LIMIT = 30;        // all submissions per hour, in case of a flood from many IPs
const GLOBAL_WINDOW_MS = 60 * 60 * 1000;

const req = $input.first().json;
const body = req.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) return [];
if (JSON.stringify(body).length > MAX_BODY) return [];

const str = (v) => (typeof v === 'string' ? v.trim() : '');
const types = {
  bug:             { label: 'Bug report',      color: 0xE5484D },
  feature_request: { label: 'Feature request', color: 0x3E63DD },
  suggestion:      { label: 'Suggestion',      color: 0x30A46C },
  other:           { label: 'Other',           color: 0x8B8D98 }
};
const type = types[str(body.type)];
const title = str(body.title);
const description = str(body.description);
const version = str(body.version).slice(0, 40) || 'unknown';
const os = str(body.os).slice(0, 200) || 'unknown';
if (!type || !title || !description) return [];
if (title.length > MAX_TITLE || description.length > MAX_DESCRIPTION) return [];

// Rate limit (static data persists between production executions of an active workflow).
const store = $getWorkflowStaticData('global');
const now = Date.now();
const h = req.headers || {};
const ip = String(h['cf-connecting-ip'] || h['x-real-ip'] || (h['x-forwarded-for'] || '').split(',')[0] || 'unknown').trim();
store.ips = store.ips || {};
for (const [k, list] of Object.entries(store.ips)) {
  const kept = list.filter((t) => now - t < PER_IP_WINDOW_MS);
  if (kept.length) store.ips[k] = kept; else delete store.ips[k];
}
store.all = (store.all || []).filter((t) => now - t < GLOBAL_WINDOW_MS);
const mine = store.ips[ip] || [];
if (mine.length >= PER_IP_LIMIT || store.all.length >= GLOBAL_LIMIT) return [];
store.ips[ip] = [...mine, now];
store.all.push(now);

return [{
  json: {
    discord: {
      username: 'Luma Feedback',
      allowed_mentions: { parse: [] },   // user text must never ping @everyone, roles or users
      embeds: [{
        title: `[${type.label}] ${title}`,
        description,
        color: type.color,
        fields: [
          { name: 'Version', value: version, inline: true },
          { name: 'OS', value: os, inline: true }
        ],
        timestamp: new Date().toISOString()
      }]
    }
  }
}];
